{"file_text": ".settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    background: #f8f9fa;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #ffffff;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.sidebar-title {
    font-size: 1.25rem;
    font-weight: 600;
    padding: 0 1.5rem;
    margin-bottom: 1rem;
    color: #1a1a2e;
}

.nav-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    color: #555;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.nav-item:hover {
    background: #f0f4ff;
    color: #1a1a2e;
}

.nav-item.active {
    background: #e8f0fe;
    color: #1967d2;
    border-left-color: #1967d2;
    font-weight: 500;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content Area */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
    position: relative;
}

.section-panel h3 {
    font-size: 1.5rem;
    font-weight: 600;
    color: #1a1a2e;
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #e0e0e0;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label,
.group-label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #d0d0d0;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
    background: #fff;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #1967d2;
    box-shadow: 0 0 0 3px rgba(25, 103, 210, 0.1);
}

/* Avatar */
.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #e0e0e0;
    flex-shrink: 0;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #eee;
    font-size: 0.75rem;
    color: #888;
}

.avatar-url-display {
    flex: 1;
}

.avatar-url-display input {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #d0d0d0;
    border-radius: 6px;
    font-size: 0.9rem;
}

.avatar-url-display label {
    font-weight: 500;
    font-size: 0.9rem;
    color: #333;
    margin-bottom: 0.4rem;
    display: block;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.15s;
}

.btn-primary {
    background: #1967d2;
    color: #fff;
}

.btn-primary:hover {
    background: #1557b0;
}

.btn-secondary {
    background: #e8e8e8;
    color: #333;
}

.btn-secondary:hover {
    background: #d0d0d0;
}

.btn-danger {
    background: #d93025;
    color: #fff;
}

.btn-danger:hover {
    background: #b5221b;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle Rows */
.toggle-group {
    margin-bottom: 1.25rem;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
    cursor: pointer;
}

.toggle-row span {
    font-size: 0.95rem;
    color: #333;
}

.toggle-switch {
    width: 20px;
    height: 20px;
    accent-color: #1967d2;
}

/* Channels */
.channels-section {
    margin-top: 1.5rem;
}

.channels-section h4 {
    font-size: 1rem;
    font-weight: 500;
    margin-bottom: 0.75rem;
}

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
}

.channel-item span {
    font-size: 0.9rem;
    color: #555;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.25rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 1rem;
    background: #fafafa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    color: #333;
}

.panel-header:hover {
    background: #f0f0f0;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

.info-text {
    font-size: 0.85rem;
    color: #666;
    margin-bottom: 1.25rem;
}

/* Two Factor */
.two-factor-section {
    margin-bottom: 1.5rem;
}

.status-badge {
    font-size: 0.75rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-weight: 500;
}

.status-badge.enabled {
    background: #e6f4ea;
    color: #1e8e3e;
}

.status-badge.disabled {
    background: #fce8e6;
    color: #d93025;
}

/* Sessions Table */
.sessions-section {
    margin-top: 1.5rem;
}

.sessions-section h4 {
    font-size: 1rem;
    font-weight: 500;
    margin-bottom: 0.75rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th {
    text-align: left;
    padding: 0.6rem 0.75rem;
    border-bottom: 2px solid #e0e0e0;
    font-weight: 500;
    color: #555;
}

.sessions-table td {
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #f0f0f0;
}

.current-badge {
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    background: #e8f0fe;
    color: #1967d2;
    border-radius: 4px;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 12px;
    padding: 1.5rem 2rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15);
}

.modal-dialog h4 {
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
}

.modal-dialog p {
    color: #555;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.radio-item input[type="radio"] {
    accent-color: #1967d2;
}

/* Appearance Preview */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border-radius: 8px;
    border: 1px solid #e0e0e0;
    transition: all 0.2s ease;
}

.preview-area h5 {
    margin-bottom: 0.5rem;
    font-size: 0.95rem;
}

.preview-theme-light {
    background: #ffffff;
    color: #1a1a2e;
}

.preview-theme-dark {
    background: #1a1a2e;
    color: #e8e8e8;
}

.preview-theme-system {
    background: #f0f4ff;
    color: #333;
}

.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 0.95rem;
}

.preview-font-large {
    font-size: 1.15rem;
}

.preview-compact .preview-card {
    padding: 0.5rem;
}

.preview-card {
    margin-top: 0.75rem;
    padding: 0.85rem;
    border-radius: 6px;
    border: 1px solid currentColor;
    opacity: 0.7;
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.preview-title {
    font-weight: 600;
}

.preview-body {
    opacity: 0.8;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    padding: 0.75rem 1.25rem;
    border-radius: 8px;
    display: flex;
    align-items: center;
    gap: 1rem;
    font-size: 0.9rem;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
    z-index: 2000;
    animation: slideIn 0.25s ease;
}

.toast.success {
    background: #e6f4ea;
    color: #1e8e3e;
    border: 1px solid #a8dab5;
}

.toast.error {
    background: #fce8e6;
    color: #d93025;
    border: 1px solid #f5c6cb;
}

.toast-close {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: inherit;
    opacity: 0.7;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Loading */
.loading-spinner {
    text-align: center;
    padding: 3rem;
    color: #888;
    font-size: 1rem;
}
